  tip.y = 64;

  const places = sectionPanel(column, { name: "Places", gap: 24 });
  await text(places, "Places", { style: "heading/panel", color: "gray/900" });
  const grid = frame(places, { name: "grid", dir: "HORIZONTAL", gap: 12, wrap: true, align: "MIN" });
